  items: pv!LLMResponse,
  expression: #"SYSTEM_SYSRULES_fromJson_v1"(
    regexfirstmatch(
      "\{(.*?)\}",
      fv!item
    )
  )
)

APP_MAIL_POLLER:#"SYSTEM_SYSRULES_forEach"(
  items: #"SYSTEM_SYSRULES_queryEntity"(
    entity: #"_a-0000ef02-3502-8000-9bf1-011c48011c48_1557667",
    query: #"SYSTEM_SYSRULES_query"(
      logicalExpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
        operator: "AND",
        filters: {
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "APP_MAIL_POLLER_ID",
            operator: "in",
            value: pv!etiquetaXcorreo[#"urn:appian:record-field:v1:76845980-0d36-4ec8-b5d3-b0700159ddfd/6459fe0c-816e-4666-a512-6d5bcfbaa191"]
          )
        },
        ignoreFiltersWithEmptyValues: true
      ),
      pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 100)
    )
  ).data,
  expression: #"urn:appian:function:v1:a:update"(
    data: #"urn:appian:function:v1:a:update"(data: fv!item, index: "ESTADO", value: 2),
    index: "CLASSIFYING",
